# Initialize the account balance as a global variable
account_balance = 0

def manage_account():
    """Manages a bank account using if/else statements."""

    while True:
        print("Welcome to the bank account manager!")
        print(f"Account balance: {account_balance}")

        action = input("Enter 'd' for deposit, 'w' for withdraw, or 'q' to quit: ").lower()

        if action == 'd':
            deposit_amount = float(input("Enter the amount to deposit: "))
            if deposit_amount > 0:
                account_balance += deposit_amount
                print(f"Deposit successful. New account balance: {account_balance}")
            else:
                print("Deposit amount must be positive. Please try again.")

        elif action == 'w':
            withdraw_amount = float(input("Enter the amount to withdraw: "))
            if withdraw_amount > 0 and account_balance >= withdraw_amount:
                account_balance -= withdraw_amount
                print(f"Withdrawal successful. New account balance: {account_balance}")
            else:
                print("Insufficient funds or withdrawal amount must be positive. Please try again.")

        elif action == 'q':
            print("Goodbye!")
            break

        else:
            print("Invalid action. Please try again.")

# Call the manage_account function
manage_account()
```

This program will run in an infinite loop, allowing users to deposit, withdraw, or quit the account manager at any time. The account balance will be updated and displayed after each action.
